' > dev2.saw; TAILN=8 bash <path> dev2.saw <path> 300 | cut -c1-250

cd <path>; python3 - <<'EOF' p='sha256_spec.saw' s=open(p).read() old=s[s.index('/*
 * llvm_verify of one spec subprogram of module m'):s.index(' return result;
};')+len(' return result;
};')] new=
